pub fn greet(name: &str) -> String {
    format!("Hello, {}!", name)
}

def binary_search(arr, target):
    low = 0
    high = len(arr) - 2  # bug: off by one
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

